mapper.select:
SELECT day, pv, uv
FROM link_stats_daily
WHERE tenant_id = #{param1}
  AND link_id = #{param2}
  AND day >= #{param3}
  AND day <= #{param4}
ORDER BY day ASC

SELECT agg.day, agg.pv, COALESCE(scope_stats.uv, agg.uv) AS uv
FROM (
    SELECT day, SUM(pv) AS pv, SUM(uv) AS uv
    FROM link_stats_daily
    WHERE tenant_id = #{param1}
      AND day >= #{param2}
      AND day <= #{param3}
    GROUP BY day
) agg
LEFT JOIN analytics_scope_stats_daily scope_stats
  ON scope_stats.tenant_id = #{param1}
 AND scope_stats.scope_type = 'tenant'
 AND scope_stats.scope_id = 0
 AND scope_stats.day = agg.day
ORDER BY agg.day ASC

SELECT agg.day, agg.pv, COALESCE(scope_stats.uv, agg.uv) AS uv
FROM (
    SELECT s.day, SUM(s.pv) AS pv, SUM(s.uv) AS uv
    FROM link_stats_daily s
    JOIN analytics_link_catalog c
      ON c.tenant_id = s.tenant_id
     AND c.link_id = s.link_id
    WHERE s.tenant_id = #{param1}
      AND c.application_id = #{param2}
      AND s.day >= #{param3}
      AND s.day <= #{param4}
    GROUP BY s.day
) agg
LEFT JOIN analytics_scope_stats_daily scope_stats
  ON scope_stats.tenant_id = #{param1}
 AND scope_stats.scope_type = 'application'
 AND scope_stats.scope_id = #{param2}
 AND scope_stats.day = agg.day
ORDER BY agg.day ASC

SELECT agg.day, agg.pv, COALESCE(scope_stats.uv, agg.uv) AS uv
FROM (
    SELECT s.day, SUM(s.pv) AS pv, SUM(s.uv) AS uv
    FROM link_stats_daily s
    JOIN analytics_link_catalog c
      ON c.tenant_id = s.tenant_id
     AND c.link_id = s.link_id
    WHERE s.tenant_id = #{param1}
      AND c.domain_id = #{param2}
      AND s.day >= #{param3}
      AND s.day <= #{param4}
    GROUP BY s.day
) agg
LEFT JOIN analytics_scope_stats_daily scope_stats
  ON scope_stats.tenant_id = #{param1}
 AND scope_stats.scope_type = 'domain'
 AND scope_stats.scope_id = #{param2}
 AND scope_stats.day = agg.day
ORDER BY agg.day ASC


SELECT COALESCE(SUM(s.pv), 0) AS total_pv
FROM link_stats_daily s
JOIN analytics_link_catalog c
  ON c.tenant_id = s.tenant_id
 AND c.link_id = s.link_id
WHERE s.tenant_id = #{tenantId}
  AND c.application_id = #{applicationId}
  AND s.day >= #{fromInclusiveUtc}
  AND s.day < #{toExclusiveUtc}
